(async () => {
  const errors = [];
  window.addEventListener('error', event => errors.push(event.message));
  const check = (condition, message) => { if (!condition) throw new Error(message); };
  const pause = ms => new Promise(resolve => setTimeout(resolve, ms));
  const make = (label, left = 8, top = 12) => {
    const field = document.createElement('label');
    field.className = 'q-field probe';
    field.style.left = left + 'px'; field.style.top = top + 'px';
    const caption = document.createElement('span'); caption.className='q-field__label'; caption.textContent=label;
    const input = document.createElement('input'); input.value='123'; input.setAttribute('aria-describedby','validation');
    field.append(caption,input); document.body.appendChild(field);
    return field;
  };
  const over = field => {
    const rect = field.getBoundingClientRect();
    field.dispatchEvent(new PointerEvent('pointerover', {bubbles:true, pointerType:'mouse', clientX:rect.left+10, clientY:rect.top+10}));
  };
  const move = (field, x, y) => field.dispatchEvent(new PointerEvent('pointermove', {bubbles:true, pointerType:'mouse', clientX:x, clientY:y}));
  const out = field => field.dispatchEvent(new PointerEvent('pointerout', {bubbles:true, relatedTarget:document.body, pointerType:'mouse'}));
  const visible = () => { const item=document.getElementById('dn-field-hover-hint'); return item && !item.hidden && item.classList.contains('dn-field-hover-hint-visible'); };
  const hint = () => document.getElementById('dn-field-hover-hint');
  try {
    const first = make('Aspect ratio',innerWidth-155,8);
    const second = make('Missing values',8,80);
    const original = first.getBoundingClientRect().toJSON();
    over(first); await pause(400);
    check(!visible(),'Hover hints must wait before appearing');
    await pause(100);
    check(visible(),'The existing 450 ms appearance delay changed');
    const style=getComputedStyle(hint());
    check(style.backgroundColor==='rgb(117, 117, 117)' && style.color==='rgb(250, 250, 250)' && style.fontSize==='10px','Hints must match the footer tooltip style');
    check(style.transitionProperty==='opacity' && style.transitionDuration==='0.3s','Hints need a gentle opacity transition');
    out(first);
    check(!visible() && !hint().hidden && hint().getAttribute('aria-hidden')==='true','Mouse leave must allow a fade out');
    await pause(350);
    check(hint().hidden,'The tooltip must be hidden after fading out');
    over(second); await pause(500);
    check(visible() && hint().textContent==='Choose how missing values are handled.','Only the current field may show a hint');
    const secondRect=second.getBoundingClientRect();
    check(hint().getBoundingClientRect().left===secondRect.left+22 && hint().getBoundingClientRect().top===secondRect.top+28,'The hint must open beside the pointer, below the field label');
    move(second,secondRect.left+40,secondRect.top+20);
    check(visible() && hint().getBoundingClientRect().left===secondRect.left+52 && hint().getBoundingClientRect().top===secondRect.top+38,'Moving within a field must move its hint without restarting the delay');
    out(second); over(first); await pause(500);
    check(hint().textContent==='Plot width divided by height.','Aspect ratio hint is unclear');
    const box=hint().getBoundingClientRect();
    check(box.left>=8 && box.right<=innerWidth-7 && box.top>=8 && box.bottom<=innerHeight-7,'Hint escaped the viewport');
    check(JSON.stringify(first.getBoundingClientRect().toJSON())===JSON.stringify(original),'Hover changed the field geometry');
    check(first.querySelector('input').getAttribute('aria-describedby')==='validation dn-field-hover-hint','Validation description was lost');
    document.body.classList.add('dn-field-hints-disabled');
    await pause(0);
    check(!visible(),'Turning hints off must immediately dismiss a visible hint');
    check(hint().hidden,'Disabling field hints must cancel a pending fade');
    check(first.querySelector('input').getAttribute('aria-describedby')==='validation','Hint did not restore the validation description');
    const dynamic=make('Source 2 transform formula',8,160);
    over(dynamic); await pause(500);
    check(!visible(),'Newly created fields must respect disabled hints');
    const number=dynamic.querySelector('input');
    number.type='number';number.min='0.000001';number.max='1200';number.step='10';number.value='300';
    check(number.form?.noValidate,'Dynamic fields must suppress native validation hover messages even when field hints are off');
    check(number.validity.stepMismatch && number.validationMessage && !number.checkValidity(),'Suppressing browser helpers must retain numeric constraints and validation APIs');
    let validated=false;
    number.addEventListener('invalid',()=>{validated=true;},{once:true});
    check(!number.reportValidity() && validated,'Application validation listeners must still receive invalid edits');
    const invalid=new Event('invalid',{bubbles:false,cancelable:true});
    check(!number.dispatchEvent(invalid) && invalid.defaultPrevented,'Browser validation bubbles must be suppressed');
    number.stepUp();
    check(Math.abs(Number(number.value)-300.000001)<1e-9 && number.step==='10' && number.min==='0.000001' && number.max==='1200','Native number stepping or bounds changed');
    number.type='text';number.value='123';
    document.body.classList.add('dn-field-help-enabled');
    const help=document.createElement('span');
    help.className='dn-field-help-icon';
    help.title='Detailed help stays separate and can explain the operation, its units, and how it changes the source data.';
    dynamic.appendChild(help);
    over(help); await pause(500);
    check(!visible() && getComputedStyle(help).display!=='none','Detailed help must remain available independently');
    check(help.title.startsWith('Detailed help stays separate'),'Detailed help content changed');
    document.body.classList.remove('dn-field-hints-disabled');
    over(dynamic); await pause(500);
    check(visible() && hint().textContent==='Transform this source using Python / NumPy.','Dynamic fields must use the current preference');
    check(dynamic.querySelector('input').value==='123','Hover changed the field value');
    const reset=document.createElement('button');reset.className='q-btn';reset.title='Reset limits';dynamic.appendChild(reset);
    over(reset); await pause(500);
    check(!visible() && reset.title==='Reset limits','Field hints must not replace action-button tooltips');
    const link=make('Source (public file link)',8,240);
    check(window.dnascapeFieldHintText(link)==='Public URL of the file to load.','Link hints must describe URLs');
    const axes=make('Z max',8,300);
    check(window.dnascapeFieldHintText(axes)==='Highest value shown on this axis.','Axis range hint is unclear');
    const named=make('A very long data filename.tsv',8,360);
    named.dataset.dnHint='Choose the dataset to display.';
    check(window.dnascapeFieldHintText(named)==='Choose the dataset to display.','An explicit hint was replaced by a filename');
    const native=make('MSE threshold',8,420);
    native.querySelector('input').dataset.dnHint='Stop below this mean squared error; 0 disables.';
    check(window.dnascapeFieldHintText(native)==='Stop below this mean squared error; 0 disables.','A native input annotation was ignored');
    over(native); await pause(500);
    over(native.querySelector('input'));
    check(visible() && hint().textContent==='Stop below this mean squared error; 0 disables.','Moving within a field restarted or replaced its hint');
    const picker=document.createElement('div');picker.className='q-color-picker';document.body.appendChild(picker);
    const red=make('R');picker.appendChild(red);
    check(window.dnascapeFieldHintText(red)==='Red colour channel.','Colour picker fields need meaningful hints');
    const form=document.createElement('form');document.body.appendChild(form);
    const owned=make('Time window (min)',innerWidth-155,innerHeight-45);
    form.appendChild(owned);
    // Remove the former owner to model a field originally mounted in a form.
    owned.querySelector('input').removeAttribute('form');
    await pause(0);
    over(owned);await pause(500);
    check(owned.querySelector('input').form===form && form.noValidate,'Existing form ownership must be preserved');
    const edgeBox=hint().getBoundingClientRect();
    check(edgeBox.right<=innerWidth-7 && edgeBox.bottom<=innerHeight-7 && edgeBox.top<innerHeight-45,'Pointer hints must flip above the pointer near the bottom and stay within the right edge');
    check(document.querySelectorAll('#dn-field-hover-hint').length===1,'Multiple hover boxes were created');
    document.getElementById('result').textContent=JSON.stringify({passed:true,errors});
  } catch (error) {
    document.getElementById('result').textContent=JSON.stringify({passed:false,error:String(error.stack||error),errors});
  }
})();
